"kind": "propose",
"summary": "Adjust liveness probe timeout to match health check latency",
"hypotheses": [
  {
    "root_cause_class": "probe_timeout_too_short",
    "summary": "Liveness probe timeout (1s) is shorter than health check latency (2s+)",
    "supporting": ["probe_timeouts", "killed_during_startup", "ev-container_logs_tail"],
    "contradicting": [],
    "missing": ["application_bug"],
    "status": "supported"
  },
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "Startup probe failures occur before app is ready",
    "supporting": ["killed_during_startup", "probe_kills"],
    "contradicting": [],
    "missing": ["application_bug"],
    "status": "supported"
  },
  {
    "root_cause_class": "insufficient_evidence",
    "summary": "No memory metrics to confirm OOM",
    "supporting": ["memory_data_available"],
    "contradicting": [],
    "missing": ["memory_at_limit_before_kill"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "inventory",
    "uid": "uid-deployment-inventory"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Liveness probe timeout increased to 5s to match health check latency",
  "rationale": "Pods are killed during startup due to liveness probe timeouts (1s) while health checks take 2s+. Logs show normal operation after startup. Increasing timeout to 5s aligns with observed health check latency. No memory metrics available to confirm OOM, but probe failures align with startup issues.",
  "cited_evidence_ids": ["ev-target_events", "ev-pod_states", "ev-rollout_history", "ev-referenced_config", "ev-container_logs_tail"],
  "cited_predicates": ["killed_during_startup", "probe_timeouts", "probe_kills", "failure_onset_after_rollout", "oom_killed_current_revision", "memory_data_available"]
}
}
